import { useEffect, useState } from 'react'

/**
 * PWA service-worker update notification banner.
 *
 * CSS classes (.sw-update-prompt, .sw-update-prompt__btn) are generated by
 * daisypick/plugin in tailwind.config.js. Removing that plugin from the plugins
 * array causes this component to lose all its styling.
 */
export function SwUpdateBanner() {
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    if (!('serviceWorker' in navigator)) return

    const handler = () => setVisible(true)
    navigator.serviceWorker.addEventListener('controllerchange', handler)
    return () => navigator.serviceWorker.removeEventListener('controllerchange', handler)
  }, [])

  if (!visible) return null

  return (
    <div className="sw-update-prompt is-visible" role="status" aria-live="polite">
      A new version is available.
      <button
        className="sw-update-prompt__btn"
        onClick={() => window.location.reload()}
      >
        Reload
      </button>
    </div>
  )
}
